      function escapeHtml(value) {
        return String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
          };

          return entities[character];
        });
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName") {
          if (!trimmedValue) {
            return "Full name is required.";
          }

          if (trimmedValue.length < 2) {
            return "Enter your full name.";
          }
        }

        if (name === "email") {
          if (!trimmedValue) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
        }

        if (name === "phone" && trimmedValue && !PHONE_PATTERN.test(trimmedValue)) {
          return "Use a valid phone number format, such as (555) 123-4567.";
        }

        return "";
      }

      function FormField({ id, label, type, placeholder, value, error, helperText, required }) {
        const helperMarkup = helperText
          ? '<div class="helper-text" id="' + id + '-helper">' + helperText + "</div>"
          : "";
        const describedBy = [helperText ? id + "-helper" : "", id + "-error"].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              placeholder="${placeholder}"
              value="${escapeHtml(value)}"
              aria-invalid="${error ? "true" : "false"}"
              aria-describedby="${describedBy}"
              ${required ? "required" : ""}
            />
            ${helperMarkup}
            <div class="error-text" id="${id}-error">${error ? escapeHtml(error) : ""}</div>
          </div>
        `;
      }

