              ${FormField({
                id: "fullName",
                label: "Full name",
                type: "text",
                placeholder: "Jordan Lee",
                value: state.values.fullName,
                error: state.errors.fullName,
                required: true
              })}
              ${FormField({
                id: "email",
                label: "Email address",
                type: "email",
                placeholder: "jordan@example.com",
                value: state.values.email,
                error: state.errors.email,
                required: true
              })}
              ${FormField({
                id: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "(555) 123-4567",
                value: state.values.phone,
                error: state.errors.phone,
                helperText: "Optional. Use a format like (555) 123-4567 or 555-123-4567.",
                required: false
              })}
              <button class="submit-button" type="submit">Submit request</button>
              <p class="success-text" id="form-success">${state.successMessage}</p>
            </form>
          </section>
        `;
      }

