        return `
          <section class="hero-panel">
            <div>
              <div class="eyebrow">Support team online</div>
              <h1>Fast help for every product question.</h1>
              <p class="hero-copy">
                Reach the support team with a quick message. We route every request to the right specialist,
                so billing, onboarding, and technical issues all get a faster response.
              </p>
            </div>
            <div class="feature-list">
