                icon: "01",
                title: "Helpful, human replies",
                description: "Share your details once and pick up the conversation with the right team."
              })}
              ${FeatureItem({
                icon: "02",
                title: "Clear next steps",
                description: "We review each message and respond with guidance tailored to your issue."
              })}
              ${FeatureItem({
                icon: "03",
                title: "Built for modern teams",
                description: "A clean support entry point that feels consistent with a polished product UI."
              })}
            </div>
          </section>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            ${SupportHero()}
            ${ContactForm()}
          </main>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();

        const form = document.getElementById("support-form");
        const fieldNames = ["fullName", "email", "phone"];

        fieldNames.forEach((fieldName) => {
          const input = document.getElementById(fieldName);

          input.addEventListener("input", (event) => {
            state.values[fieldName] = event.target.value;
            state.errors[fieldName] = validateField(fieldName, event.target.value);
            state.successMessage = "";
            render();
          });

          input.addEventListener("blur", (event) => {
            state.values[fieldName] = event.target.value;
            state.errors[fieldName] = validateField(fieldName, event.target.value);
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          fieldNames.forEach((fieldName) => {
            state.errors[fieldName] = validateField(fieldName, state.values[fieldName]);
          });

          const hasErrors = fieldNames.some((fieldName) => state.errors[fieldName]);

          if (hasErrors) {
            state.successMessage = "";
            render();
            return;
          }

          state.successMessage = "Thanks. Your support request is ready to send.";
          render();
        });
      }

      render();
    </script>
