        background: linear-gradient(135deg, #2563eb, #0ea5e9);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
        box-shadow: 0 16px 30px rgba(37, 99, 235, 0.26);
      }

