        display: grid;
        place-items: center;
        padding: 32px 20px;
      }

      .page-shell {
        width: min(100%, 1100px);
        display: grid;
        grid-template-columns: minmax(0, 1.1fr) minmax(320px, 460px);
        gap: 28px;
        align-items: stretch;
      }

      .hero-panel,
      .form-panel {
        border: 1px solid var(--panel-border);
        background: var(--panel);
        backdrop-filter: blur(16px);
        border-radius: 28px;
        box-shadow: var(--shadow);
      }

      .hero-panel {
        padding: 40px;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 28px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 14px;
        border-radius: 999px;
        background: rgba(37, 99, 235, 0.08);
        color: #1d4ed8;
        font-size: 0.86rem;
        font-weight: 600;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.1rem, 5vw, 3.75rem);
        line-height: 1;
